/* eslint-disable */
// Generated by Launchpad (recipe vercel-queue): @vercel/queue, off Vercel.
//
// send() puts a message on a pg-boss queue in the app's own Postgres,
// and a background process, launchpad/queue-worker.mjs, delivers it to the
// consumer route, the way Vercel does. The route answers only that worker:
// without the secret Launchpad gives both, it is a 404 to everyone else.
// The calls, the options and the retry rules are @vercel/queue's.

export type MessageMetadata = {
  messageId: string;
  deliveryCount: number;
  createdAt: Date;
  expiresAt: Date;
  topicName: string;
  consumerGroup: string;
  region: string;
};
export type RetryDirective = { afterSeconds: number } | { acknowledge: true };
export type RetryHandler = (error: unknown, metadata: MessageMetadata) => RetryDirective | void | undefined;
export type MessageHandler<T = unknown> = (message: T, metadata: MessageMetadata) => Promise<void> | void;
export type SendOptions = {
  idempotencyKey?: string;
  retentionSeconds?: number;
  delaySeconds?: number;
  headers?: Record<string, string>;
};
export type SendResult = { messageId: string | null };
export type Message<T = unknown> = { messageId: string; payload: T };

// A message nobody could deliver in this long is dropped, as on Vercel.
const RETENTION_SECONDS = 86400;

let boss: Promise<any> | undefined;
const made = new Set<string>();

async function queueFor(topic: string): Promise<any> {
  boss ??= (async () => {
    const mod: any = await import(/* webpackIgnore: true */ /* turbopackIgnore: true */ "pg-boss");
    const PgBoss = mod.PgBoss ?? mod.default ?? mod;
    // Sending only: the worker supervises the queue.
    const b = new PgBoss({ connectionString: process.env.DATABASE_URL, schema: "launchpad_queue", supervise: false, schedule: false });
    b.on("error", (e: Error) => console.error("queue:", e.message));
    await b.start();
    return b;
  })();
  const b = await boss;
  if (!made.has(topic)) {
    if (b.createQueue) await b.createQueue(topic, { retryLimit: 5, expireInSeconds: 960 }).catch(() => {});
    made.add(topic);
  }
  return b;
}

export async function send<T = unknown>(topicName: string, payload: T, options: SendOptions = {}): Promise<SendResult> {
  const created = Date.now();
  const data = { payload, delivery: 1, created, expires: created + 1000 * (options.retentionSeconds ?? RETENTION_SECONDS) };
  const b = await queueFor(topicName);
  const id = await b.send(topicName, data, {
    startAfter: options.delaySeconds || undefined,
    singletonKey: options.idempotencyKey,
  });
  return { messageId: id ?? null };
}

type Handlers = Record<string, Record<string, MessageHandler<any>>>;

export function handleCallback<T = unknown>(
  handler: MessageHandler<T> | Handlers,
  options: { visibilityTimeoutSeconds?: number; retry?: RetryHandler } = {},
): (request: Request) => Promise<Response> {
  // Typed as a route handler; { request } is taken too, as @vercel/queue does.
  return async function launchpadQueueCallback(requestOrEvent: Request): Promise<Response> {
    const req: Request = requestOrEvent instanceof Request ? requestOrEvent : (requestOrEvent as any).request;
    const secret = process.env.LAUNCHPAD_QUEUE_SECRET;
    if (!secret || req.headers.get("x-launchpad-queue-secret") !== secret) {
      return new Response("Not Found", { status: 404 });
    }
    const d = JSON.parse(req.headers.get("x-launchpad-delivery") || "{}");
    const metadata: MessageMetadata = {
      messageId: String(d.messageId),
      deliveryCount: Number(d.deliveryCount) || 1,
      createdAt: new Date(d.createdAt || Date.now()),
      expiresAt: new Date(d.expiresAt || Date.now() + RETENTION_SECONDS * 1000),
      topicName: String(d.topicName),
      consumerGroup: String(d.consumerGroup || "default"),
      region: "launchpad",
    };
    const message = (await req.json()) as T;
    const fn = typeof handler === "function" ? handler : Object.values(handler[metadata.topicName] || {})[0];
    if (!fn) return Response.json({ acknowledge: true, error: "no handler for " + metadata.topicName }, { status: 500 });
    try {
      await fn(message, metadata);
      return Response.json({ ok: true });
    } catch (error) {
      console.error(`queue ${metadata.topicName}: delivery ${metadata.deliveryCount} of ${metadata.messageId} failed:`, error);
      const r = options.retry?.(error, metadata);
      if (r && "acknowledge" in r && r.acknowledge) return Response.json({ acknowledge: true }, { status: 500 });
      if (r && "afterSeconds" in r) return Response.json({ retry: { afterSeconds: r.afterSeconds } }, { status: 500 });
      return Response.json({ retry: {} }, { status: 500 });
    }
  };
}
